```javascript
import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  Color
} from 'three/webgpu';
import {
  MeshStandardNodeMaterial
} from 'three/webgpu';
import {
  uv,
  mix,
  vec3
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const bandWidth = 6.8;
  const bandHeight = 2.0;

  const group = new Group();

  // --- band plane ---
  const bandGeo = new PlaneGeometry(bandWidth, bandHeight);
  const bandMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2
  });

  const colorBottom = new Color(0x121218);
  const colorTop = new Color(0x0b0b10);
  bandMat.colorNode = mix(
    vec3(colorBottom.r, colorBottom.g, colorBottom.b),
    vec3(colorTop.r, colorTop.g, colorTop.b),
    uv().y
  );
  const bandMesh = new Mesh(bandGeo, bandMat);
  bandMesh.position.z = 0;
  group.add(bandMesh);

  // --- top hairline ---
  const hairlineGeo = new BoxGeometry(bandWidth, 0.006, 0.01);
  const hairlineMat = new MeshStandardNodeMaterial({
    color: new Color(0x23232b),
    roughness: 0.6,
    metalness: 0.2
  });
  const topHair = new Mesh(hairlineGeo, hairlineMat);
  topHair.position.set(0, 1.0 - 0.003, 0.01);
  group.add(topHair);

  // --- bottom hairline (positioned later) ---
  const bottomHair = new Mesh(hairlineGeo.clone(), hairlineMat.clone());
  bottomHair.position.set(0, -0.75, 0.01);
  group.add(bottomHair);

  // --- accent bar ---
  const accentGeo = new BoxGeometry(0.3, 0.02, 0.01);
  const accentMat = new MeshStandardNodeMaterial({
    color: new Color(0xff2a38),
    emissive: new Color(0xff2a38),
    emissiveIntensity: 1.4,
    roughness: 0.5,
    metalness: 0.2
  });
  const accentBar = new Mesh(accentGeo, accentMat);
  accentBar.position.set(-3.4 + 1.0, 0.68, 0.01);
  group.add(accentBar);

  // --- text layout ---
  const leftBlockX = -3.4 + 0.5; // left margin for wordmark
  const colXPositions = [-1.4, 0.175, 1.75];
  const roleConfig = {
    wordmark: { fontSize: 0.62, letterSpacing: 0.02, align: 'left', color: '#e8ecf2' },
    'column-header': { fontSize: 0.09, letterSpacing: 0.12, align: 'left', color: '#e8ecf2' },
    link: { fontSize: 0.13, letterSpacing: 0, align: 'left', color: '#e8ecf2' },
    legal: { fontSize: 0.09, letterSpacing: 0.04, align: 'center', color: '#e8ecf2' }
  };

  // Y positions (approximate)
  const wordmarkY = 0.8;
  const colHeaderY = 0.5;
  const linkYBase = 0.3;
  const linkStep = 0.13 * 1.8; // line height
  const legalY = -0.625;

  let colIndex = -1;
  let linkIndex = 0;
  const linkObjects = [];

  items.forEach((item, idx) => {
    const role = item.role;
    const text = item.text;
    const cfg = roleConfig[role];
    if (!cfg) return;

    const textObj = ctx.fontAtlas.createText(text, {
      fontSize: cfg.fontSize,
      letterSpacingPx: cfg.letterSpacing,
      align: cfg.align,
      color: cfg.color,
      maxWidthPx: (role === 'wordmark' || role === 'legal') ? bandWidth : (role === 'link' ? 1.2 : 1.2)
    });

    if (role === 'wordmark') {
      textObj.position.set(leftBlockX, wordmarkY, 0.02);
    } else if (role === 'column-header') {
      colIndex++;
      linkIndex = 0;
      textObj.position.set(colXPositions[colIndex], colHeaderY, 0.02);
    } else if (role === 'link') {
      const x = colXPositions[colIndex];
      const y = colHeaderY - 0.09 * 1.2 - (linkIndex + 1) * linkStep;
      textObj.position.set(x, y, 0.02);
      linkIndex++;
      linkObjects.push(textObj);
    } else if (role === 'legal') {
      textObj.position.set(0, legalY, 0.02);
    }

    group.add(textObj);
  });

  // --- link hover interactions ---
  const linkTimelines = [];
  linkObjects.forEach((obj) => {
    const originalColor = '#e8ecf2';
    const hoverColor = '#ff2a38';
    // Store reference to the material (assume first child mesh has material)
    let mesh = obj;
    if (obj.children && obj.children.length > 0) {
      mesh = obj.children[0];
    }
    const initialMat = mesh.material;

    const onEnter = () => {
      if (linkTimelines[obj.uuid]) {
        linkTimelines[obj.uuid].kill();
      }
      const tl = gsap.to(initialMat, {
        color: hoverColor,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true
      });
      gsap.to(obj.position, {
        z: 0.02,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true
      });
      linkTimelines[obj.uuid] = tl;
    };

    const onLeave = () => {
      if (linkTimelines[obj.uuid]) {
        linkTimelines[obj.uuid].kill();
      }
      const tl = gsap.to(initialMat, {
        color: originalColor,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true
      });
      gsap.to(obj.position, {
        z: 0,
        duration: 0.14,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        overwrite: true
      });
      linkTimelines[obj.uuid] = tl;
    };

    obj.userData.handlers = {
      pointerenter: onEnter,
      pointerleave: onLeave
    };
  });

  // --- entrance animation ---
  const enterTL = gsap.timeline({ paused: true });
  enterTL.fromTo(group.position,
    { y: 0.2, opacity: 0 },
    { y: 0, opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
  );
  enterTL.play();

  // --- cleanup ---
  const cleanupResources = [
    bandGeo, bandMat, bandMesh,
    hairlineGeo, topHair, bottomHair,
    accentGeo, accentMat, accentBar,
    ...linkObjects,
    ...group.children.filter(c => c.geometry && c.geometry !== bandGeo && c.geometry !== hairlineGeo && c.geometry !== accentGeo)
  ];

  group.userData.cleanup = () => {
    enterTL.kill();
    Object.values(linkTimelines).forEach(tl => tl.kill());
    cleanupResources.forEach(obj => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
      if (obj.children) {
        obj.traverse(child => {
          if (child.geometry) child.geometry.dispose();
          if (child.material) child.material.dispose();
        });
      }
    });
  };

  return group;
}
